{
  "suspects": [
    {
      "sentenceId": "sent-109",
      "reason": "上下文討論因明論典，'佛福論'應為著名因明論典名稱漏字或誤聽。",
      "suspectedMissingTerm": "釋量論",
      "promptHints": [
        "法稱論師的《釋量論》"
      ]
    },
    {
      "sentenceId": "sent-136",
      "reason": "佛教因明術語，'不經'應為'不淨'或特定論典/概念誤聽，結合上下文'外境'與'無方分'，疑為'不淨'或'不成'等詞漏字。但更可能指《入中論》或相關破外境論述中的特定詞彙。考慮到ASR常見錯誤，'不經'極可能是'不成'（因明三支之一）或'不淨'。然而結合'有不經不講的外境'語意不通，推測原句可能涉及'不成'或特定論典名。暫標記為疑似漏字/誤聽關鍵術語。",
      "suspectedMissingTerm": "不成",
      "promptHints": [
        "因明三支：宗、因、喻；其中因有九過，包括不成"
      ]
    },
    {
      "sentenceId": "sent-205",
      "reason": "'阿賴也是'為ASR誤聽，正確佛教名相為'阿賴耶識'。",
      "suspectedMissingTerm": "阿賴耶識",
      "promptHints": [
        "唯識學核心概念：第八識阿賴耶識"
      ]
    },
    {
      "sentenceId": "sent-275",
      "reason": "'關帶秘義所依'語意不順，疑為'觀待密意所依'或類似因明/中觀術語漏字。'故義是義'亦疑為'故義非義'或特定論述漏字。此處高度疑似關鍵名相誤聽。",
      "suspectedMissingTerm": "觀待密意",
      "promptHints": [
        "中觀應成派區分：了義與不了義，常涉及'觀待'（dependence）"
      ]
    },
    {
      "sentenceId": "sent-320",
      "reason": "'善為體觀'疑為'勝義諦'或'世俗諦'相關術語誤聽，或'善說'等詞。結合'亦非了義'，此處應討論經論判教。'配觀'疑為'比量'或'現量'誤聽。",
      "suspectedMissingTerm": "勝義諦",
      "promptHints": [
        "佛教二諦：世俗諦與勝義諦；了義與不了義的判定標準"
      ]
    },
    {
      "sentenceId": "sent-338",
      "reason": "'四顯'疑為'四種'或特定論典章節名誤聽。'自信'在佛教因明中通常指'自相'（svabhava）或'自證分'，此處'向無自信'語意不通，疑為'向無自性'或'無自相'漏字/誤聽。",
      "suspectedMissingTerm": "自性",
      "promptHints": [
        "中觀核心概念：諸法無自性（空性）"
      ]
    },
    {
      "sentenceId": "sent-381",
      "reason": "'葡萄切朗'為ASR嚴重誤聽，結合上下文'指的是誰'、'手不見了'，此處應討論印度哲學或佛教因明中關於'我'（Atman）或特定論敵的比喻。'葡萄切朗'極可能是'補特伽羅'（Pudgala，即人/我）的誤聽。",
      "suspectedMissingTerm": "補特伽羅",
      "promptHints": [
        "佛教術語：補特伽羅（意譯為數取趣、人、我），常討論其與五蘊關係"
      ]
    }
  ]
}
